import csv,collections,statistics
tr=list(csv.DictReader(open('b3_pvk_stack_train.csv')))
for field in ['substrate','etl','htl','backcontact','deposition']:
 d=collections.defaultdict(list)
 for r in tr: d[r[field]].append(float(r['target']))
 print('\n',field)
 for k,v in sorted(d.items(),key=lambda kv:(statistics.mean(kv[1]),len(kv[1])),reverse=True)[:20]:
  print(f'{statistics.mean(v):5.2f} n={len(v):2d} {k}')
