python - <<'PY'
import csv,difflib
tr=list(csv.DictReader(open('b3_pvk_stack_train.csv'))); po={x['candidate_id']:x for x in csv.DictReader(open('b3_pvk_stack_pool.csv'))}
cols=['substrate','etl','htl','backcontact','deposition']
for cid in 'c005 c013 c017 c025 c031 c035 c043 c045 c051 c064 c068 c073 c080 c081 c083 c085 c099'.split():
 p=po[cid]; print('\n###',cid, '|'.join(p[c] for c in cols))
 sims=[]
 for n,t in enumerate(tr,2):
  fs=[difflib.SequenceMatcher(None,p[c].lower(),t[c].lower()).ratio() for c in cols]
  s=sum(fs)/5
  sims.append((s,float(t['target']),n,t))
 for s,y,n,t in sorted(sims,reverse=True)[:5]: print(f'{y:6.3f} sim={s:.3f} line={n}:', '|'.join(t[c] for c in cols))
PY

